    // MBT Workflow Explorer (L1)
    'mbtw.title': 'MBT Workflow Explorer',
    'mbtw.desc': 'Follow the model-based testing pipeline end to end: build a model, pick a generation criterion, derive abstract tests, concretize them, execute against the system, and judge conformance. Click any stage for its role, a worked example, and its common failure modes.',
    'mbtw.stage.num': 'Stage {n}',
    'mbtw.stage.model.name': 'Model',
    'mbtw.stage.model.role': 'Turn the informal spec into a precise behavioral model — typically a finite-state machine — that captures the states the system can be in and the events that move it between them. Everything downstream is derived from this model, so a wrong model means wrong tests.',
    'mbtw.stage.criterion.name': 'Generation criterion',
    'mbtw.stage.criterion.role': 'Choose how thoroughly the model should be exercised: cover every state, every transition, every pair of adjacent transitions, or every round-trip path. The criterion turns the model into a concrete set of test obligations.',
    'mbtw.stage.abstract.name': 'Abstract test suite',
    'mbtw.stage.abstract.role': 'Walk the model to satisfy the criterion, producing event sequences at the model level — "validCard · push · timeout". These are abstract: they name events, not real API calls or data values yet.',
    'mbtw.stage.concretize.name': 'Concretization',
    'mbtw.stage.concretize.role': 'Map each abstract event onto a concrete action against the real system — an API call, a UI gesture, a clock advance — and pick real input values. This is where the model meets the actual system under test (SUT).',
    'mbtw.stage.execute.name': 'Execution',
    'mbtw.stage.execute.role': 'Run the concrete test against the SUT and record what actually happens at each step: the observed outputs and state transitions.',
    'mbtw.stage.verdict.name': 'Conformance verdict',
    'mbtw.stage.verdict.role': 'Compare the observed SUT behavior against what the model predicted. Match → pass; divergence → fail, and the failing step pinpoints either a system bug or a model that no longer matches reality.',
    'mbtw.detail.role': 'Role',
    'mbtw.detail.example': 'Example',
    'mbtw.detail.failures': 'Failure modes',
    'mbtw.example.in': 'Input',
    'mbtw.example.out': 'Output',
    'mbtw.model.failure1': 'Over-abstraction: the model omits a state or event that actually matters, so whole classes of bugs become untestable.',
    'mbtw.model.failure2': 'Model drift: the spec changes but the model is not updated, so tests verify yesterday\'s behavior.',
    'mbtw.criterion.failure1': 'Criterion too weak (state coverage only): broken transitions between reachable states slip through.',
    'mbtw.criterion.failure2': 'Criterion too strong (all paths): the obligation set explodes combinatorially and the suite never finishes.',
    'mbtw.abstract.failure1': 'Infeasible sequence: the walk produces an event order the real system can never reach.',
    'mbtw.abstract.failure2': 'Redundant tests: many abstract tests cover the same transition, inflating the suite without adding coverage.',
    'mbtw.concretize.failure1': 'Mapping gap: an abstract event has no concrete counterpart, so the test cannot be run.',
    'mbtw.concretize.failure2': 'Bad input data: the chosen concrete values trigger a guard the abstract test never intended to exercise.',
    'mbtw.execute.failure1': 'Non-determinism: timing or async behavior makes the same test pass and fail across runs.',
    'mbtw.execute.failure2': 'Observability gap: the SUT\'s internal state cannot be observed, so divergence is detected late or not at all.',
    'mbtw.verdict.failure1': 'False fail: the test fails because the model is wrong, not the system — and someone "fixes" a correct system.',
    'mbtw.verdict.failure2': 'False pass: a too-coarse comparison treats a divergent output as a match, hiding a real bug.',
    'mbtw.modes.title': 'Offline vs Online MBT',
    'mbtw.mode.offline.name': 'Offline MBT',
    'mbtw.mode.online.name': 'Online MBT',
    'mbtw.mode.offline.r1': 'Tests are generated fully before execution begins.',
    'mbtw.mode.offline.r2': 'Produces a reusable, inspectable test suite.',
    'mbtw.mode.offline.r3': 'Best for deterministic systems and regression runs.',
    'mbtw.mode.online.r1': 'Generation and execution interleave — the next step is chosen from the observed state.',
    'mbtw.mode.online.r2': 'No stored suite; the model walk adapts on the fly.',
    'mbtw.mode.online.r3': 'Best for large or non-deterministic systems and long-running soak tests.',
    'mbtw.bridge.vmodel.title': 'Open the V-Model Explorer — model-based testing operationalizes the right-hand verification side of the V.',
    'mbtw.quiz.prompt': 'In the MBT pipeline, a conformance test fails. The model predicts the system should reach state "Locked" but the SUT stays "Open". What does this verdict tell you?',
    'mbtw.quiz.a': 'The generation criterion was too weak.',
    'mbtw.quiz.b': 'The abstract test suite had a redundant sequence.',
    'mbtw.quiz.c': 'Either the system has a bug, or the model no longer matches the system — the failing step tells you where to look.',
    'mbtw.quiz.d': 'Concretization always causes this; it can be ignored.',
    'mbtw.quiz.correct': 'Correct. A conformance failure is a divergence between model and system: the bug is in one of the two, and the failing step localizes it.',
    'mbtw.quiz.wrong': 'Not quite. A conformance verdict compares observed vs predicted behavior — a fail means the model and the system disagree, so the fault is in one of them.',
    'mbtw.lab.prompt': 'Pick a system you know (an ATM, a turnstile, a checkout flow). Sketch its FSM in 3–5 states, choose a generation criterion, and explain what one abstract test would look like — and one realistic way concretization could go wrong.',


