    'cadence.stage.code.roles': 'Developers',
    'cadence.stage.code.feedback': 'Defects accumulate silently — none of this code has been verified.',
    'cadence.stage.testphase.name': 'Test Phase',
    'cadence.stage.testphase.activities': 'All testing crammed into one phase — unit, integration, system and acceptance — under schedule pressure.',
    'cadence.stage.testphase.roles': 'A separate QA team',
    'cadence.stage.testphase.feedback': 'Defects from every earlier stage surface at once, far from where and when they were introduced.',
    'cadence.stage.release.name': 'Release',
    'cadence.stage.release.activities': 'Ship the product. Any testing now is firefighting hotfixes in production.',
    'cadence.stage.release.roles': 'Operations',
    'cadence.stage.release.feedback': 'Defects that escaped the test phase are now found by users — the most expensive place of all.',
    'cadence.detail.activities': 'Activities',
    'cadence.detail.roles': 'Who tests',
    'cadence.compare.title': 'Agile cadence vs waterfall',
    'cadence.compare.woven': 'Stages with testing woven in',
    'cadence.compare.latency': 'Feedback latency',
    'cadence.compare.escape': 'Defect escape',
    'cadence.latency.agile': 'Minutes to days',
    'cadence.latency.waterfall': 'Weeks to months',
    'cadence.escape.agile': 'Low — caught near the source',
    'cadence.escape.waterfall': 'High — found late or in production',
    'cadence.shiftleft.note': 'Shift-left: move each testing activity to the earliest stage it can run. The earlier a defect is caught, the cheaper it is to fix.',
    'cadence.bridge.vmodel.title': 'Open the V-Model Explorer — the V-model pairs each build stage with a test stage; the agile cadence collapses that into a continuous loop.',
    'cadence.bridge.defectcost.title': 'Open the Defect Cost Explorer — quantifies why catching a defect late costs so much more.',
    'cadence.quiz.prompt': 'What best describes how testing fits into an agile sprint, compared with a waterfall project?',
    'cadence.quiz.a': 'Agile skips testing; waterfall does all of it — that is the whole difference.',
    'cadence.quiz.b': 'Both run testing only at the end, but agile sprints are shorter.',
    'cadence.quiz.c': 'In agile, testing is a continuous whole-team activity woven through every stage; in waterfall it is a separate phase after coding.',
    'cadence.quiz.d': 'Agile moves all testing to the very start of the sprint, before any code exists.',
    'cadence.quiz.correct': 'Correct. Agile spreads testing across refinement, development, story testing and review — feedback is continuous, not deferred to one phase.',
    'cadence.quiz.wrong': 'Not quite. Agile does not skip or front-load all testing — it weaves testing through every stage of the sprint, so feedback is continuous instead of deferred to a separate end phase.',
    'cadence.lab.prompt': 'Which testing activity does your team habitually defer to "later"? Name it, say which sprint stage it should happen in, and estimate the cost of deferring it.',

    // Definition of Ready / Done Explorer (M3)
    'agileTab.gates': 'Ready / Done Gates',
    'gate.title': 'Definition of Ready / Done Explorer',
    'gate.desc': 'DoR and DoD are agile\'s quality gates. The Definition of Ready gates a story into the sprint — is it clear enough to start? The Definition of Done gates it out — is it truly finished? Toggle each criterion and watch latent issues get caught at a gate, or leak to production when the gate is weak.',
    'gate.dor.title': 'Definition of Ready',
