    'gate.crit.dor-data': 'Test data and environment are identified',
    'gate.crit.dor-deps': 'External dependencies are resolved or stubbed',
    'gate.crit.dor-small': 'Story is small enough to finish within the sprint',
    'gate.crit.dod-tests': 'All automated tests pass in CI',
    'gate.crit.dod-review': 'Code has been reviewed and merged',
    'gate.crit.dod-ac': 'Every acceptance criterion has been verified',
    'gate.crit.dod-nosev1': 'No known Sev-1 / Sev-2 defects remain',
    'gate.issue.ambiguous-ac': 'Acceptance criterion read two different ways by dev and tester',
    'gate.issue.missing-test-data': 'No realistic test data — the story cannot be exercised',
    'gate.issue.blocked-dep': 'A dependency on another team is unresolved mid-sprint',
    'gate.issue.oversized': 'Story too big to finish — testing is rushed at the end',
    'gate.issue.failing-regression': 'A regression test is red but the story shipped anyway',
    'gate.issue.unreviewed-code': 'Code merged without review — a defect no second pair of eyes caught',
    'gate.issue.unverified-ac': 'An acceptance criterion was never actually checked',
    'gate.issue.known-defect': 'A known Sev-2 defect shipped because "done" was declared early',
    'gate.gate.dor': 'Definition of Ready',
    'gate.gate.dod': 'Definition of Done',
    'gate.caughtAt': 'caught at {gate}',
    'gate.leaked': '⚠ leaked to production',
    'gate.result.title': 'Run the story through the gates',
    'gate.result.summary': '{caught} issue(s) caught at a gate · {leaked} leaked to production',
    'gate.contrast': 'DoR criteria are about clarity — can we start? DoD criteria are about completeness — are we finished? A weak gate does not stop the work; it just lets the defect through to a more expensive stage.',
    'gate.bridge.defectcost.title': 'Open the Defect Cost Explorer — quantifies how much more a leaked defect costs downstream.',
    'gate.bridge.bdd.title': 'Open the BDD / Gherkin Explorer — testable acceptance criteria are exactly what a DoR criterion demands.',
    'gate.quiz.prompt': 'What is the essential difference between the Definition of Ready and the Definition of Done?',
    'gate.quiz.a': 'They are the same checklist, just applied twice for safety.',
    'gate.quiz.b': 'DoR is written by the team; DoD is written by the customer.',
    'gate.quiz.c': 'DoR gates a story into the sprint — is it clear enough to start? DoD gates it out — is it truly finished?',
    'gate.quiz.d': 'DoD is optional; only the Definition of Ready is mandatory in Scrum.',
    'gate.quiz.correct': 'Correct. DoR is an entry gate (clarity to start), DoD is an exit gate (completeness to finish) — different questions at different points.',
    'gate.quiz.wrong': 'Not quite. DoR is the entry gate — is the story clear enough to start? — and DoD is the exit gate — is it truly finished? Two different gates, two different questions.',
    'gate.lab.prompt': 'Which Definition of Done criterion does your team quietly treat as "optional"? Name it, and describe a defect that has shipped — or could ship — because that criterion is skipped.',

    // Three Amigos / Example Mapping Explorer (M5)
