    'ctp.quiz.prompt': 'A new end-to-end test takes 8 minutes to run. Which pipeline tier should it be assigned to?',
    'ctp.quiz.a': 'The commit tier — run it on every push so failures are caught instantly.',
    'ctp.quiz.b': 'The pull-request tier — 8 minutes is fine to block every PR.',
    'ctp.quiz.c': 'The nightly tier — an 8-minute test would wreck commit-tier feedback; run it on a slower cadence.',
