    'rdebt.bridge.rbt.title': 'Open the Risk-Based Testing Explorer — risk-based selection is how you keep a growing suite affordable.',
    'rdebt.bridge.flaky.title': 'Open the Flaky Diagnosis Explorer — flaky tests are the biggest single driver of regression-suite debt.',
    'rdebt.quiz.prompt': 'A regression test starts failing intermittently — sometimes red, sometimes green — with no related code change. What is the best immediate response?',
    'rdebt.quiz.a': 'Delete the test at once — an unreliable test is worthless.',
    'rdebt.quiz.b': 'Ignore it; just re-run the pipeline until it goes green.',
    'rdebt.quiz.c': 'Quarantine it — move it out of the blocking suite — and schedule a fix, so it stops eroding trust in the pipeline.',
    'rdebt.quiz.d': 'Block every merge until someone fixes it, however long that takes.',
    'rdebt.quiz.correct': 'Correct. Quarantine keeps the flaky test from blocking everyone while preserving the signal; pair it with a scheduled fix so the suite does not rot.',
    'rdebt.quiz.wrong': 'Not quite. Deleting loses coverage, ignoring trains the team to distrust red, and blocking all merges halts delivery. Quarantine the test and schedule a fix.',
    'rdebt.lab.prompt': 'In your own regression suite, which class of test most deserves pruning — obsolete feature tests, slow duplicative end-to-end tests, or chronically flaky ones? Estimate the maintenance cost it carries.',

