    // MBT 工作流程探索器（L1）
    'mbtw.title': 'MBT 工作流程探索器',
    'mbtw.desc': '完整走過模型驅動測試的管線：建立模型、選擇生成準則、推導抽象測試、具體化、對系統執行、判定一致性。點擊任一階段可看它的角色、實例演練，以及常見的失效模式。',
    'mbtw.stage.num': '階段 {n}',
    'mbtw.stage.model.name': '模型',
    'mbtw.stage.model.role': '把非形式化的規格轉成精確的行為模型——通常是有限狀態機——描述系統可能處於的狀態，以及在狀態間移動的事件。後續所有步驟都由此模型推導，模型錯則測試全錯。',
    'mbtw.stage.criterion.name': '生成準則',
    'mbtw.stage.criterion.role': '決定要多徹底地操練模型：涵蓋每個狀態、每個轉移、每對相鄰轉移，或每條來回路徑。準則把模型轉成一組具體的測試義務。',
    'mbtw.stage.abstract.name': '抽象測試套件',
    'mbtw.stage.abstract.role': '走訪模型以滿足準則，產生模型層級的事件序列——「validCard · push · timeout」。它們是抽象的：只命名事件，還沒有真正的 API 呼叫或資料值。',
    'mbtw.stage.concretize.name': '具體化',
    'mbtw.stage.concretize.role': '把每個抽象事件對應到對真實系統的具體動作——API 呼叫、UI 操作、時鐘前進——並挑選真實的輸入值。模型在此與受測系統（SUT）接軌。',
    'mbtw.stage.execute.name': '執行',
    'mbtw.stage.execute.role': '對 SUT 執行具體測試，記錄每一步實際發生的事：觀察到的輸出與狀態轉移。',
    'mbtw.stage.verdict.name': '一致性判定',
    'mbtw.stage.verdict.role': '把觀察到的 SUT 行為與模型的預測比對。相符→通過；分歧→失敗，而失敗的那一步能指出究竟是系統有缺陷，還是模型已不符現實。',
