    'mbtw.criterion.failure1': '準則太弱（只做狀態涵蓋）：可達狀態間損壞的轉移會漏掉。',
    'mbtw.criterion.failure2': '準則太強（所有路徑）：義務集合組合爆炸，套件永遠跑不完。',
