    'efsm.bridge.symbex.title': '開啟符號執行探索器——路徑可行性正是一次路徑條件的可滿足性檢查。',
    'efsm.bridge.logic.title': '開啟邏輯涵蓋探索器——守衛就是一個述詞，子句綁定以同樣方式求解它。',
