    'gate.quiz.a': '它們是同一份檢查清單，只是為了保險套用兩次。',
    'gate.quiz.b': 'DoR 由團隊撰寫；DoD 由客戶撰寫。',
    'gate.quiz.c': 'DoR 把故事擋「進」sprint——它夠清楚、可以開始了嗎？DoD 把故事擋「出」——它真的完成了嗎？',
    'gate.quiz.d': 'DoD 是選用的；在 Scrum 中只有 Definition of Ready 是必要的。',
    'gate.quiz.correct': '正確。DoR 是進入閘門（清晰到可以開始），DoD 是離開閘門（完整到可以結束）——在不同時點問不同的問題。',
    'gate.quiz.wrong': '不太對。DoR 是進入閘門——故事夠清楚可以開始了嗎？——DoD 是離開閘門——它真的完成了嗎？兩個不同閘門、兩個不同問題。',
    'gate.lab.prompt': '你的團隊默默把哪一條 Definition of Done 準則當成「選用」？說出它，並描述一個因為跳過該準則而已經出貨——或可能出貨——的缺陷。',

